script.source:
param([switch]$Execute)
$ErrorActionPreference = 'Stop'
$projectRoot = (Resolve-Path -LiteralPath 'C:\public\project-hyle\hyle').Path
$taskStage = Join-Path $projectRoot '.scratch\architecture-refactor-2026-10-18\plain-grouped-cuda'
$planPath = Join-Path $taskStage 'cleanup-plan.json'
$cleanupPlan = Get-Content -LiteralPath $planPath -Raw | ConvertFrom-Json
$linkPlan = Get-Content -LiteralPath $cleanupPlan.current_link_plan.path -Raw | ConvertFrom-Json
$protectedFiles = [System.Collections.Generic.HashSet[string]]::new([System.StringComparer]::OrdinalIgnoreCase)
foreach ($inputFile in $linkPlan.inputs) { [void]$protectedFiles.Add([IO.Path]::GetFullPath($inputFile.path)) }
[void]$protectedFiles.Add([IO.Path]::GetFullPath($cleanupPlan.final_image.path))

foreach ($required in @($cleanupPlan.archive, $cleanupPlan.final_image, $cleanupPlan.final_test_image, $cleanupPlan.current_link_plan)) {
    $item = Get-Item -LiteralPath $required.path
    if ($item.Length -ne $required.bytes -or (Get-FileHash -LiteralPath $required.path -Algorithm SHA256).Hash -ine $required.sha256) {
        throw "Retained evidence or current build changed: $($required.path)"
    }
}
$checkedTargets = @()
foreach ($target in $cleanupPlan.targets) {
    $resolved = (Resolve-Path -LiteralPath $target.path).Path
    $allowedRoot = $taskStage + [IO.Path]::DirectorySeparatorChar
    if (-not $resolved.StartsWith($allowedRoot, [StringComparison]::OrdinalIgnoreCase)) {
        throw "Cleanup target escaped the intended task directory: $resolved"
    }
    if ($protectedFiles.Contains($resolved)) { throw "Cleanup target is a current link input/image: $resolved" }
    $item = Get-Item -LiteralPath $resolved
    if ($item.PSIsContainer -or ($item.Attributes -band [IO.FileAttributes]::ReparsePoint)) {
        throw "Only exact ordinary files can be deleted: $resolved"
    }
    if ($item.Length -ne $target.bytes -or (Get-FileHash -LiteralPath $resolved -Algorithm SHA256).Hash -ine $target.sha256) {
        throw "Cleanup target changed: $resolved"
    }
    $checkedTargets += $target
}
if (-not $Execute) {
    $checkedTargets | Select-Object path, bytes
    Write-Output "Verified $($checkedTargets.Count) exact files; reclaimable bytes $($cleanupPlan.reclaimable_bytes). Use -Execute to delete."
    return
}
$removed = @()
foreach ($target in $checkedTargets) {
    Remove-Item -LiteralPath $target.path -Force
    if (Test-Path -LiteralPath $target.path) { throw "Deletion did not complete: $($target.path)" }
    $removed += $target
}
if (-not (Test-Path -LiteralPath $cleanupPlan.final_image.path) -or -not (Test-Path -LiteralPath $cleanupPlan.final_test_image.path)) { throw 'Current benchmark/test image was removed' }
$receipt = [ordered]@{
    passed = $true
    recorded_utc = [DateTime]::UtcNow.ToString('o')
    script = [ordered]@{ path = $PSCommandPath; sha256 = (Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant(); source = (Get-Content -LiteralPath $PSCommandPath -Raw) }
    archive_sha256 = $cleanupPlan.archive.sha256
    removed = $removed
    reclaimed_bytes = ($removed | Measure-Object -Property bytes -Sum).Sum
    current_image_and_objects_retained = $true
}
$receiptPath = Join-Path $projectRoot 'docs\evidence\performance\plain-grouped-cuda-2026-10-20.cleanup.json'
$receipt | ConvertTo-Json -Depth 12 | Set-Content -LiteralPath $receiptPath -Encoding utf8NoBOM
Write-Output "Removed $($removed.Count) files; reclaimed $($receipt.reclaimed_bytes) bytes. Current image and linked objects retained."
